from pathlib import Path
import json,re
root=Path('docs/design/mobile-pdf-permissions-task-v1');root.mkdir(exist_ok=True);assert not (root/'index.html').exists()
old=Path('docs/design/mobile-pdf-settings-v3/index.html').read_text(encoding='utf-8');base=old.split('</style>')[0]
css='''
/* permissions-task */
.pdf-permissions-task{--permission-limited-bg:#fff0dc;--permission-limited-ink:#895817;position:absolute;inset:0;z-index:14;display:flex;flex-direction:column;min-height:0;overflow:hidden;background:var(--bg);color:var(--ink)}.permissions-surface{display:flex;flex:1;flex-direction:column;min-height:0}.permissions-header{display:flex;align-items:center;gap:8px;min-height:64px;padding:7.5px 8px;border-bottom:1px solid var(--line);flex:none}.permissions-header h1{flex:1;min-width:0;margin:0;font-size:1.25rem;line-height:1.5;letter-spacing:normal;font-weight:700;overflow-wrap:anywhere}.permissions-icon{display:grid;place-items:center;flex:0 0 48px;width:48px;height:48px;padding:0;border:0;background:transparent;color:var(--muted)}
.permissions-body{flex:1;min-height:0;padding:16px;overflow:auto;overscroll-behavior:contain}.permissions-card{display:flex;align-items:center;gap:12px;min-height:80px;padding:14px 16px;border:1px solid var(--line);border-radius:12px;background:var(--surface)}.permissions-card>svg{flex:none;color:var(--primary)}.permissions-card>span{flex:1;min-width:0}.permissions-card strong{display:block;font-size:1rem;line-height:1.5;font-weight:650;overflow-wrap:anywhere}.permissions-card small{display:block;margin-top:4px;color:var(--muted);font-size:.875rem;line-height:1.5}
.permissions-rows{list-style:none;margin:20px 0 0;padding:0;border:1px solid var(--line);border-radius:12px;overflow:hidden;background:var(--surface)}.permissions-rows>li+li{border-top:1px solid var(--line)}.permissions-row{display:grid;grid-template-columns:24px minmax(0,1fr) auto 20px;align-items:center;gap:12px;width:100%;min-height:80px;padding:14px;border:0;background:transparent;color:var(--ink);text-align:left}.permissions-row>svg{color:var(--muted);flex:none}.permissions-row-text{min-width:0}.permissions-row strong{display:block;font-size:1rem;line-height:1.5;font-weight:650;overflow-wrap:anywhere}.permissions-row-text small{display:block;margin-top:4px;font-size:.875rem;line-height:1.5;color:var(--muted);overflow-wrap:anywhere}.permissions-status{display:inline-block;justify-self:start;flex:none;padding:4px 10px;border-radius:99px;background:var(--primary-soft);color:var(--primary);font-size:.8125rem;line-height:1.5;font-weight:600;white-space:nowrap}.permissions-status.is-limited{background:var(--permission-limited-bg);color:var(--permission-limited-ink)}.permissions-row:active{background:var(--panel)}
.permissions-footer,.permissions-dialog-footer{display:flex;gap:8px;flex:none;padding:12px 16px calc(12px + env(safe-area-inset-bottom));border-top:1px solid var(--line);background:var(--bg);max-height:45dvh;overflow:auto}.permissions-footer>.button,.permissions-dialog-footer>.button{flex:1;min-width:0;min-height:48px;padding:11px 10px;border-radius:10px;font-size:.875rem;line-height:1.7142857143;font-weight:400}
.permissions-layer{position:absolute;inset:0;z-index:16;display:flex;align-items:flex-end;background:#14261d66}.permissions-dialog{display:flex;flex-direction:column;width:100%;max-height:calc(100% - 16px);min-height:0;background:var(--bg);border:1px solid var(--line);border-radius:16px 16px 0 0;overflow:hidden}.permissions-dialog-header{display:flex;align-items:center;gap:8px;min-height:64px;padding:7.5px 8px 7.5px 16px;border-bottom:1px solid var(--line);flex:none}.permissions-dialog h2{flex:1;min-width:0;margin:0;font-size:1.25rem;line-height:1.5;font-weight:700;overflow-wrap:anywhere}.permissions-dialog-body{padding:16px;min-height:0;overflow:auto;overscroll-behavior:contain}.permissions-detail-status{margin:0 0 12px}.permissions-detail-copy{margin:0;font-size:1rem;line-height:1.75;overflow-wrap:anywhere;white-space:pre-wrap}.pdf-permissions-task button{-webkit-tap-highlight-color:transparent}
.phone.theme-dark .pdf-permissions-task{--permission-limited-bg:#45372a;--permission-limited-ink:#f5d9ad}
@media(max-width:340px){.permissions-header h1{font-size:1.125rem}.permissions-card{padding:12px}.permissions-row{grid-template-columns:24px minmax(0,1fr) 20px;padding:12px;gap:10px}.permissions-row>svg:first-child{grid-column:1;grid-row:1/span 2}.permissions-row-text{grid-column:2;grid-row:1}.permissions-row>.permissions-status{grid-column:2;grid-row:2}.permissions-row>.permissions-chevron{grid-column:3;grid-row:1/span 2}.permissions-dialog h2{font-size:1.125rem}}
@media(max-height:400px){.permissions-header{min-height:49px;padding:0 8px}.permissions-header h1{font-size:1rem}.permissions-body{padding:12px}.permissions-footer,.permissions-dialog-footer{padding:8px 12px}.permissions-footer>.button,.permissions-dialog-footer>.button{padding:8px 6px;font-size:.75rem;line-height:1.5}.permissions-dialog-header{min-height:49px;padding:0 8px 0 12px}.permissions-dialog h2{font-size:1rem}.permissions-layer{padding-top:8px}.permissions-dialog{max-height:100%}.permissions-dialog-body{padding:12px}}
'''
icons={}
for name in ['arrow-left','circle-help','file-text','book-open','copy','message-square','chevron-right','x']:
 file='circle-question-mark' if name=='circle-help' else name;code=Path('node_modules/lucide-vue-next/dist/esm/icons/'+file+'.js').read_text(encoding='utf-8');literal=re.search(r'createLucideIcon\("[^\"]+", (\[[\s\S]*?\])\);',code).group(1);nodes=json.loads(re.sub(r'(?<=[{,])\s*(\w+)\s*:',r'"\1":',literal));icons[name]=''.join('<'+tag+' '+' '.join(k+'="'+v+'"' for k,v in attrs.items() if k!='key')+' />' for tag,attrs in nodes)
settings=old.split('<script>')[1].split('</script>')[0].replace('阅读导航.pdf','受限阅读指南.pdf').replace('第 3 / 9 页','第 1 / 6 页').replace('继续阅读 · 第 3 页','继续阅读 · 第 1 页')
settings+="\ndocument.querySelector('.pdf-settings-rows').insertAdjacentHTML('beforeend','<button class=\"pdf-setting-row\"><strong>文档权限</strong><small>部分操作受限</small>'+svg('chevron-right',20)+'</button>');\n"
script=r'''
const screen=new URLSearchParams(location.search).get('screen')||'restricted';
if(screen==='settings-entry'){
SETTINGS
}else{
const icons=ICONS,icon=(n,size=22,cls='')=>`<svg class="${cls}" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]}</svg>`,dark=screen==='restricted-dark',known=screen!=='unknown',copy=['no-annotations','allowed','source-folder'].includes(screen),annotate=['no-copy','allowed','source-folder','annotation-detail'].includes(screen),local=screen!=='source-folder',detail=screen==='copy-detail'||screen==='detail-short-320-200'?'copy':screen==='annotation-detail'?'annotate':screen==='reading-detail'?'reading':'';
if(dark){document.querySelector('.phone').classList.add('theme-dark');for(const [k,v]of Object.entries({bg:'#202722',surface:'#28312a',panel:'#2d392f',ink:'#e0e8db',muted:'#acb9a8',line:'#3b473c',primary:'#aad0af','primary-soft':'#334b3b'}))document.querySelector('.phone').style.setProperty('--'+k,v)}
const state=k=>k==='reading'?'可用':!known?'未确认':k==='copy'?copy?'可用':'受限':!annotate?'受限':!local?'需导入':'可用',caps=[{id:'reading',label:'阅读与导航',sub:'原版页面 · 目录 · 书签',icon:'book-open'},{id:'copy',label:'复制与摘录',sub:'原文文字 · 阅读笔记',icon:'copy'},{id:'annotate',label:'批注操作',sub:'新增 · 修改 · 删除',icon:'message-square'}],pill=k=>`<span class="permissions-status ${state(k)==='可用'?'':'is-limited'}">${state(k)}</span>`;
const caption=k=>k==='reading'?'可阅读原版页面，翻页并使用目录和本机书签。':k==='copy'?!known?'暂未确认原文件是否允许复制，当前不复制或摘录。可重新打开文档核对。':copy?'可复制原文；已有批注可整理为独立阅读笔记。':'这份文件限制原文复制与摘录。自己的评论输入不受这项限制。':!known?'暂未确认原文件是否允许修改批注，当前保留记录和未完成输入。可重新打开文档核对。':!annotate?'这份文件限制新增、修改和删除批注。已有本机记录及未完成输入继续保留。':!local?'原文件允许批注；当前来源暂只读。先导入手机资料库，再添加或修改批注。':copy?'可选取原文高亮，也可添加、修改或删除自己的批注。':'可新增、修改或删除自己的页评论；原文摘录仍受限。';
const modal=detail?`<div class="permissions-layer"><section class="permissions-dialog"><header class="permissions-dialog-header"><h2>${caps.find(c=>c.id===detail).label}</h2><button class="permissions-icon">${icon('x')}</button></header><div class="permissions-dialog-body"><p class="permissions-detail-status">${pill(detail)}</p><p class="permissions-detail-copy">${caption(detail)}</p></div><footer class="permissions-dialog-footer"><button class="button">返回权限</button></footer></section></div>`:'';
document.querySelector('.phone').innerHTML=`<section class="pdf-permissions-task"><div class="permissions-surface"><header class="permissions-header"><button class="permissions-icon">${icon('arrow-left')}</button><h1>文档权限</h1><button class="mobile-help-trigger">${icon('circle-help',20)}</button></header><div class="permissions-body"><div class="permissions-card">${icon('file-text',24)}<span><strong>${screen==='allowed'?'普通阅读指南':!local?'文件夹阅读指南':'受限阅读指南'}.pdf</strong><small>${local?'手机资料库':'外部资料'}</small></span></div><ul class="permissions-rows">${caps.map(c=>`<li><button class="permissions-row">${icon(c.icon,24)}<span class="permissions-row-text"><strong>${c.label}</strong><small>${c.sub}</small></span>${pill(c.id)}${icon('chevron-right',20,'permissions-chevron')}</button></li>`).join('')}</ul></div><footer class="permissions-footer"><button class="button primary-button">继续阅读</button></footer></div>${modal}</section>`;
}
'''.replace('SETTINGS',settings).replace('ICONS',json.dumps(icons,ensure_ascii=False))
(root/'index.html').write_text(base+css+'</style><div class="phone"></div><script>'+script+'</script></html>',encoding='utf-8',newline='\n')
